insert into exam_simulations (id, title_de, sort_order) values (1, 'Simulation 1', 0) on conflict (id) do update set title_de = excluded.title_de, sort_order = excluded.sort_order;
insert into exam_tasks (id, simulation_id, aufgabe, task_type, title_de, prompt_de, bullet_points_de, min_words, recommended_minutes, sample_answer_de, sort_order) values ('s1-a1', 1, 1, 'Persönliche E-Mail', 'E-Mail über einen Ausflug', 'Schreiben Sie eine E-Mail an einen Freund, der nicht an Ihrem Ausflug teilnehmen konnte, weil er für die Uni lernen musste.', array['Beschreiben Sie, wo Sie waren und wie der Ausflug war.','Begründen Sie, warum Ihnen der Ausflug besonders gefallen hat.','Schlagen Sie ein Treffen vor.']::text[], 80, 20, null, 0) on conflict (id) do update set simulation_id=excluded.simulation_id, aufgabe=excluded.aufgabe, task_type=excluded.task_type, title_de=excluded.title_de, prompt_de=excluded.prompt_de, bullet_points_de=excluded.bullet_points_de, min_words=excluded.min_words, recommended_minutes=excluded.recommended_minutes, sample_answer_de=excluded.sample_answer_de, sort_order=excluded.sort_order;
insert into exam_tasks (id, simulation_id, aufgabe, task_type, title_de, prompt_de, bullet_points_de, min_words, recommended_minutes, sample_answer_de, sort_order) values ('s1-a2', 1, 2, 'Meinungsäußerung', 'Sind junge Menschen heute schlecht erzogen?', 'Schreiben Sie Ihre Meinung zu dem Diskussionsthema aus dem Fernsehen: „Sind junge Menschen heute schlecht erzogen?“.', array[]::text[], 80, 25, 'Ich bin der Meinung, dass man nicht pauschal sagen kann, dass alle jungen Menschen schlecht erzogen sind. Natürlich gibt es Jugendliche, die unhöflich wirken oder zu viel Zeit am Handy verbringen, aber das ist kein neues Phänomen. Ältere Generationen haben sich schon immer über die Jugend beschwert. Ich glaube eher, dass sich die Art der Kommunikation verändert hat. Es liegt an den Eltern und der Schule, den Kindern Werte wie Respekt und Höflichkeit im Umgang mit digitalen Medien zu vermitteln, statt sie nur zu verurteilen.', 1) on conflict (id) do update set simulation_id=excluded.simulation_id, aufgabe=excluded.aufgabe, task_type=excluded.task_type, title_de=excluded.title_de, prompt_de=excluded.prompt_de, bullet_points_de=excluded.bullet_points_de, min_words=excluded.min_words, recommended_minutes=excluded.recommended_minutes, sample_answer_de=excluded.sample_answer_de, sort_order=excluded.sort_order;
insert into exam_tasks (id, simulation_id, aufgabe, task_type, title_de, prompt_de, bullet_points_de, min_words, recommended_minutes, sample_answer_de, sort_order) values ('s1-a3', 1, 3, 'Formelle E-Mail', 'Anfrage zu einem Praktikumsangebot', 'Schreiben Sie eine E-Mail an Herrn Giessler von der Personalabteilung, um Informationen zu einem Praktikumsangebot (Zeit, Aufgaben etc.) zu erhalten.', array[]::text[], 40, 15, null, 2) on conflict (id) do update set simulation_id=excluded.simulation_id, aufgabe=excluded.aufgabe, task_type=excluded.task_type, title_de=excluded.title_de, prompt_de=excluded.prompt_de, bullet_points_de=excluded.bullet_points_de, min_words=excluded.min_words, recommended_minutes=excluded.recommended_minutes, sample_answer_de=excluded.sample_answer_de, sort_order=excluded.sort_order;
insert into exam_simulations (id, title_de, sort_order) values (2, 'Simulation 2', 1) on conflict (id) do update set title_de = excluded.title_de, sort_order = excluded.sort_order;
insert into exam_tasks (id, simulation_id, aufgabe, task_type, title_de, prompt_de, bullet_points_de, min_words, recommended_minutes, sample_answer_de, sort_order) values ('s2-a1', 2, 1, 'Persönliche E-Mail', 'E-Mail über ein neues Einkaufszentrum', 'Schreiben Sie eine E-Mail an einen Freund über ein neues Einkaufszentrum, das Sie gestern besucht haben.', array['Beschreiben Sie, was Ihnen gut gefallen hat.','Begründen Sie, warum Ihr Freund/Ihre Freundin mitkommen sollte.','Schlagen Sie einen Termin vor.']::text[], 80, 20, null, 0) on conflict (id) do update set simulation_id=excluded.simulation_id, aufgabe=excluded.aufgabe, task_type=excluded.task_type, title_de=excluded.title_de, prompt_de=excluded.prompt_de, bullet_points_de=excluded.bullet_points_de, min_words=excluded.min_words, recommended_minutes=excluded.recommended_minutes, sample_answer_de=excluded.sample_answer_de, sort_order=excluded.sort_order;
insert into exam_tasks (id, simulation_id, aufgabe, task_type, title_de, prompt_de, bullet_points_de, min_words, recommended_minutes, sample_answer_de, sort_order) values ('s2-a2', 2, 2, 'Meinungsäußerung', 'Schule schon ab 4', 'Schreiben Sie Ihre Meinung zu dem Diskussionsthema: „Schule schon ab 4“.', array[]::text[], 80, 25, 'Das Thema, Kinder schon mit vier Jahren in die Schule zu schicken, sehe ich sehr kritisch. Meiner Ansicht nach ist das viel zu früh. In diesem Alter steht die spielerische Entwicklung im Vordergrund. Wenn Kinder bereits im Kindergarten mit Leistungsdruck oder schulischen Anforderungen wie dem Erlernen von Buchstaben konfrontiert werden, geht die natürliche Freude am Entdecken verloren. Kinder brauchen Zeit zum Spielen, um ihre sozialen und emotionalen Fähigkeiten zu entwickeln. Die Schule sollte ein Ort sein, für den sie erst mit sechs oder sieben Jahren bereit sind.', 1) on conflict (id) do update set simulation_id=excluded.simulation_id, aufgabe=excluded.aufgabe, task_type=excluded.task_type, title_de=excluded.title_de, prompt_de=excluded.prompt_de, bullet_points_de=excluded.bullet_points_de, min_words=excluded.min_words, recommended_minutes=excluded.recommended_minutes, sample_answer_de=excluded.sample_answer_de, sort_order=excluded.sort_order;
insert into exam_tasks (id, simulation_id, aufgabe, task_type, title_de, prompt_de, bullet_points_de, min_words, recommended_minutes, sample_answer_de, sort_order) values ('s2-a3', 2, 3, 'Formelle E-Mail', 'Reservierung beim Autoverleih ändern', 'Schreiben Sie eine E-Mail an Herrn Cervantes von einem Autoverleih. Erklären Sie, dass Sie Ihre Reservierung von einem Kleinwagen auf ein größeres Auto ändern möchten, und entschuldigen Sie sich höflich für die Umstände.', array[]::text[], 40, 15, null, 2) on conflict (id) do update set simulation_id=excluded.simulation_id, aufgabe=excluded.aufgabe, task_type=excluded.task_type, title_de=excluded.title_de, prompt_de=excluded.prompt_de, bullet_points_de=excluded.bullet_points_de, min_words=excluded.min_words, recommended_minutes=excluded.recommended_minutes, sample_answer_de=excluded.sample_answer_de, sort_order=excluded.sort_order;
insert into exam_simulations (id, title_de, sort_order) values (3, 'Simulation 3', 2) on conflict (id) do update set title_de = excluded.title_de, sort_order = excluded.sort_order;
insert into exam_tasks (id, simulation_id, aufgabe, task_type, title_de, prompt_de, bullet_points_de, min_words, recommended_minutes, sample_answer_de, sort_order) values ('s3-a1', 3, 1, 'Persönliche E-Mail', 'Bericht über das Online-Deutschlernen', 'Berichten Sie einem Freund über das Online-Deutschlernen.', array['Beschreiben Sie, wie Sie gelernt haben.','Begründen Sie die Vorteile des Lernens mit dem Computer.','Schlagen Sie ein Treffen vor.']::text[], 80, 20, null, 0) on conflict (id) do update set simulation_id=excluded.simulation_id, aufgabe=excluded.aufgabe, task_type=excluded.task_type, title_de=excluded.title_de, prompt_de=excluded.prompt_de, bullet_points_de=excluded.bullet_points_de, min_words=excluded.min_words, recommended_minutes=excluded.recommended_minutes, sample_answer_de=excluded.sample_answer_de, sort_order=excluded.sort_order;
insert into exam_tasks (id, simulation_id, aufgabe, task_type, title_de, prompt_de, bullet_points_de, min_words, recommended_minutes, sample_answer_de, sort_order) values ('s3-a2', 3, 2, 'Meinungsäußerung', 'Persönliche Kontakte und Internet', 'Schreiben Sie Ihre Meinung zum Thema „Persönliche Kontakte und Internet“, basierend auf einem Kommentar über feste Arbeitszeiten und Flexibilität.', array[]::text[], 80, 25, 'Die Aussage in dem Kommentar kann ich gut nachvollziehen. Feste Arbeitszeiten von 9 bis 17:30 Uhr bieten eine klare Struktur, die besonders für Eltern von kleinen Kindern sehr wertvoll für die Planung des Familienlebens ist. Dennoch zeigt der Kommentar ein Problem: Wenn man Kinder hat, reicht ein starrer Zeitplan oft nicht aus. Es wäre wünschenswert, wenn Arbeitgeber mehr Flexibilität im Homeoffice oder bei den Arbeitszeiten anbieten würden, damit Beruf und Privatleben besser vereinbar sind, ohne dass der Kontakt zu den Kunden darunter leidet.', 1) on conflict (id) do update set simulation_id=excluded.simulation_id, aufgabe=excluded.aufgabe, task_type=excluded.task_type, title_de=excluded.title_de, prompt_de=excluded.prompt_de, bullet_points_de=excluded.bullet_points_de, min_words=excluded.min_words, recommended_minutes=excluded.recommended_minutes, sample_answer_de=excluded.sample_answer_de, sort_order=excluded.sort_order;
insert into exam_tasks (id, simulation_id, aufgabe, task_type, title_de, prompt_de, bullet_points_de, min_words, recommended_minutes, sample_answer_de, sort_order) values ('s3-a3', 3, 3, 'Formelle E-Mail', 'Entschuldigung beim Kursleiter', 'Schreiben Sie an Ihren Kursleiter, Herrn Weber, um sich höflich zu entschuldigen und zu berichten, warum Sie nicht zum ersten Termin des Kurses „Erfolgreich präsentieren“ kommen können.', array[]::text[], 40, 15, null, 2) on conflict (id) do update set simulation_id=excluded.simulation_id, aufgabe=excluded.aufgabe, task_type=excluded.task_type, title_de=excluded.title_de, prompt_de=excluded.prompt_de, bullet_points_de=excluded.bullet_points_de, min_words=excluded.min_words, recommended_minutes=excluded.recommended_minutes, sample_answer_de=excluded.sample_answer_de, sort_order=excluded.sort_order;
insert into exam_simulations (id, title_de, sort_order) values (4, 'Simulation 4', 3) on conflict (id) do update set title_de = excluded.title_de, sort_order = excluded.sort_order;
insert into exam_tasks (id, simulation_id, aufgabe, task_type, title_de, prompt_de, bullet_points_de, min_words, recommended_minutes, sample_answer_de, sort_order) values ('s4-a1', 4, 1, 'Persönliche E-Mail', 'E-Mail über eine Geburtstagsfeier', 'Schreiben Sie an einen Freund, der wegen Krankheit nicht zu Ihrer Geburtstagsfeier kommen konnte.', array['Beschreiben Sie die Feier.','Begründen Sie, welches Geschenk Sie besonders toll fanden.','Schlagen Sie ein Treffen vor.']::text[], 80, 20, null, 0) on conflict (id) do update set simulation_id=excluded.simulation_id, aufgabe=excluded.aufgabe, task_type=excluded.task_type, title_de=excluded.title_de, prompt_de=excluded.prompt_de, bullet_points_de=excluded.bullet_points_de, min_words=excluded.min_words, recommended_minutes=excluded.recommended_minutes, sample_answer_de=excluded.sample_answer_de, sort_order=excluded.sort_order;
insert into exam_tasks (id, simulation_id, aufgabe, task_type, title_de, prompt_de, bullet_points_de, min_words, recommended_minutes, sample_answer_de, sort_order) values ('s4-a2', 4, 2, 'Meinungsäußerung', 'Persönliche Kontakte und Internet', 'Schreiben Sie Ihre Meinung zum Thema „Persönliche Kontakte und Internet“, basierend auf einem Kommentar, der besagt, dass Internetkontakte persönliche Treffen nicht ersetzen können.', array[]::text[], 80, 25, 'Ich stimme dem Kommentar voll und ganz zu: Das Internet ist ein großartiges Werkzeug, um in Kontakt zu bleiben, besonders wenn Freunde weit weg wohnen. Es ersetzt jedoch keinesfalls ein persönliches Treffen. Bei einem direkten Gespräch kann man die Mimik und Gestik des Gegenübers wahrnehmen, was über digitale Kanäle oft verloren geht. Ich denke, soziale Medien und Videoanrufe sollten nur eine Ergänzung sein, um die Zeit zwischen echten Begegnungen zu überbrücken, aber sie sollten niemals unsere wertvollen persönlichen Treffen ersetzen.', 1) on conflict (id) do update set simulation_id=excluded.simulation_id, aufgabe=excluded.aufgabe, task_type=excluded.task_type, title_de=excluded.title_de, prompt_de=excluded.prompt_de, bullet_points_de=excluded.bullet_points_de, min_words=excluded.min_words, recommended_minutes=excluded.recommended_minutes, sample_answer_de=excluded.sample_answer_de, sort_order=excluded.sort_order;
insert into exam_tasks (id, simulation_id, aufgabe, task_type, title_de, prompt_de, bullet_points_de, min_words, recommended_minutes, sample_answer_de, sort_order) values ('s4-a3', 4, 3, 'Formelle E-Mail', 'Entschuldigung bei der Kursleiterin', 'Schreiben Sie an Ihre Kursleiterin, Frau Müller, um sich höflich zu entschuldigen und zu erklären, warum Sie den Termin zum Gespräch über Ihre persönlichen Lernziele nicht wahrnehmen können.', array[]::text[], 40, 15, null, 2) on conflict (id) do update set simulation_id=excluded.simulation_id, aufgabe=excluded.aufgabe, task_type=excluded.task_type, title_de=excluded.title_de, prompt_de=excluded.prompt_de, bullet_points_de=excluded.bullet_points_de, min_words=excluded.min_words, recommended_minutes=excluded.recommended_minutes, sample_answer_de=excluded.sample_answer_de, sort_order=excluded.sort_order;
